/* ============================================================================
   OG-FONT — the serif glyphs for the share-card images.

   Generated from Georgia REGULAR weight: the seal screen's monogram is an
   elegant engraved letter, not a heavy bold — bold letters on the share
   card were the one thing customers disliked about the first version.
   Capitals, lowercase, digits and name punctuation; run-length 4-bit alpha
   rows, compressed. Data, not code — zero font dependencies on the edge.
   ========================================================================= */
"use strict";
const zlib = require("zlib");
const RAW = "";
const GLYPHS = JSON.parse(zlib.inflateSync(Buffer.from(RAW, "base64")).toString("utf8"));
module.exports = GLYPHS;
